import {chromium,expect} from '@playwright/test';import {readFile,mkdir,writeFile} from 'node:fs/promises';
// A friend link generated by the real Share flow must deliver its question unchanged when opened fresh.
const out=process.env.UX_EVIDENCE||'.local/friend-link',base=process.env.PREVIEW_URL||'http://localhost:8098',question='What will my life look like next year?';await mkdir(out,{recursive:true});
const prediction={...JSON.parse(await readFile('docs/ux-loop/expansion-16/fixture.json','utf8')),dueDate:'2099-01-01'},browser=await chromium.launch({channel:'chrome',headless:true}),result={};
try{const context=await browser.newContext({viewport:{width:390,height:844}});await context.addInitScript(prediction=>{localStorage.setItem('crystal-ball-v1',JSON.stringify({facts:{},history:[prediction],credits:0,onboardingDone:true,ageConfirmed:true,ageBand:'adult',reduceMotion:true}));Object.defineProperty(navigator,'share',{value:async()=>{}})},prediction);
 const page=await context.newPage();await page.goto(base);await page.getByTestId('tab-history').click();await page.getByRole('button').filter({hasText:prediction.headline}).click();await page.getByTestId('share-this-glimpse').click();await page.getByTestId('share-more').click();await page.getByTestId('share-friend-link').click();await page.getByTestId('view-invitation-link').click();
 result.url=(await page.getByTestId('invitation-url').innerText()).trim();result.encodedQuestion=new URL(result.url).search;
 const friend=await browser.newContext({viewport:{width:390,height:844}});await friend.addInitScript(()=>localStorage.setItem('crystal-ball-v1',JSON.stringify({facts:{},history:[],credits:1,onboardingDone:true,ageConfirmed:true,ageBand:'adult',reduceMotion:true})));const fp=await friend.newPage();await fp.goto(result.url);
 const input=fp.getByTestId('question-input');await input.waitFor();result.received=await input.inputValue();await fp.screenshot({path:`${out}/received.png`});
 expect(result.received).toBe(question);result.passed=true}
finally{await browser.close();await writeFile(`${out}/result.json`,JSON.stringify(result,null,2))}
console.log(result);
